import java.util.Scanner;

public class lilu {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalLength = scanner.nextInt();
        int maxBracketRun = 0;
        int totalWords = 0;
        String sequenceStr = scanner.next();
        char[] sequenceChars = sequenceStr.toCharArray();
        boolean inBracketZone = false;
        int currentRun = 0;
        int tempRun = 0;

        for (int i = 0; i < totalLength; i++) {
            char c = sequenceChars[i];

            if (c == '(') {
                inBracketZone = true;
                if (tempRun != 0) {
                    maxBracketRun = Math.max(maxBracketRun, tempRun);
                    tempRun = 0;
                }
            } else if (c == ')') {
                inBracketZone = false;
            }

            if (inBracketZone) {
                if (c != '_' && c != '(' && c != ')') {
                    totalWords++;
                }
            } else {
                if (c != '_' && c != '(' && c != ')') {
                    currentRun++;
                    if (i == totalLength - 1) {
                        maxBracketRun = Math.max(maxBracketRun, currentRun);
                    }
                } else {
                    if (currentRun != 0) {
                        maxBracketRun = Math.max(maxBracketRun, currentRun);
                        currentRun = 0;
                    }
                }
            }
        }
        System.out.println(maxBracketRun + " " + totalWords);
    }
}
